package com.bank.product.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.time.LocalDateTime;
@Entity @Table(name="product_attribute_values",uniqueConstraints=@UniqueConstraint(name="uq_product_attribute_value_product_attribute",columnNames={"pav_product_id","pav_attribute_def_id"}))
public class ProductAttributeValue{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="pav_value_id") private Integer id; @Column(name="pav_product_id",nullable=false) private Integer productId; @Column(name="pav_attribute_def_id",nullable=false) private Integer attributeDefId; @Column(name="pav_value_string",length=500) private String valueString; @Column(name="pav_value_number",precision=18,scale=4) private BigDecimal valueNumber; @Column(name="pav_value_date") private OffsetDateTime valueDate; @Column(name="pav_created_by") private String createdBy; @Column(name="pav_created_date") private LocalDateTime createdDate; @Column(name="pav_updated_by") private String updatedBy; @Column(name="pav_updated_date") private LocalDateTime updatedDate; @Column(name="pav_version") private String version; @Column(name="pav_uuid") private String uuid; @Column(name="pav_crud_value") private String crudValue;
 public Integer getId(){return id;}public void setId(Integer v){id=v;}public Integer getProductId(){return productId;}public void setProductId(Integer v){productId=v;}public Integer getAttributeDefId(){return attributeDefId;}public void setAttributeDefId(Integer v){attributeDefId=v;}public String getValueString(){return valueString;}public void setValueString(String v){valueString=v;}public BigDecimal getValueNumber(){return valueNumber;}public void setValueNumber(BigDecimal v){valueNumber=v;}public OffsetDateTime getValueDate(){return valueDate;}public void setValueDate(OffsetDateTime v){valueDate=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public LocalDateTime getCreatedDate(){return createdDate;}public void setCreatedDate(LocalDateTime v){createdDate=v;}public String getUpdatedBy(){return updatedBy;}public void setUpdatedBy(String v){updatedBy=v;}public LocalDateTime getUpdatedDate(){return updatedDate;}public void setUpdatedDate(LocalDateTime v){updatedDate=v;}public String getVersion(){return version;}public void setVersion(String v){version=v;}public String getUuid(){return uuid;}public void setUuid(String v){uuid=v;}public String getCrudValue(){return crudValue;}public void setCrudValue(String v){crudValue=v;}
}
